export function clamp(value, low, high) {
  if (value < low) {
    return low;
  }
  if (value > high) {
    return high;
  }
  return value;
}

test("below range", () => { assert.equal(clamp(-5, 0, 10), 0); });
test("above range", () => { assert.equal(clamp(15, 0, 10), 10); });
